  return (
    <AssistantProvider {...options}>
      <AssistantModalElement
        label={options.title ?? "Assistant"}
        defaultOpen={defaultOpen}
        icon={<LauncherMark />}
        className={className}
        thread={<AssistantThread />}
        headerActions={
          <>
            {actions}
            <AdkArtifactsMenu compact />
          </>
        }
        banner={<AdkEscalationBanner />}
      />
    </AssistantProvider>
  )
}

